from typing import List

class Solution:
    def minMeetingRooms(self, intervals: List[List[int]]) -> int:
        best = 0
        for start, _ in intervals:
            active = 0
            for s, e in intervals:
                if s <= start < e:
                    active += 1
            best = max(best, active)
        return best

